1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"syscall"
12		"time"
13	)
14	
15	// 包裹状态。
16	const (
17		// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
18		statusInStation = "在站"
19		// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
20		statusDelivering = "配送中"
21		// statusSigned 表示包裹已签收（回执结果为签收）。
22		statusSigned = "已签收"
23		// statusFrozen 表示在站包裹因异常被冻结：站点不变，禁止交接、配送出站与整批退回。
24		statusFrozen = "异常冻结"
25		// statusInTransit 表示包裹已随某张运输单离开源站、尚未在目的站被接收：
26		// 归属站点暂记源站，禁止交接、退回、配送出站与冻结。
27		statusInTransit = "站间在途"
28	)
29	
30	// 回执结果。
31	const (
32		resultSigned = "签收"
33		resultFailed = "失败"
34	)
35	
36	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
37	type Event struct {
38		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接 | 撤销回执 | 发运 | 接收
39		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接/撤销回执为批次出发站；发运时为源站，接收时为目的站）
40		Time       time.Time `json:"time"`                 // 发生时间
41		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接/撤销/接收请求号（收件、出站、发运记录为空）
42		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）或发运/接收源站（仅发运、接收记录有）
43		To         string    `json:"to,omitempty"`         // 发运/接收目的站（仅发运、接收记录有）
44		Shipment   string    `json:"shipment,omitempty"`   // 运输单号（仅发运、接收记录有）
45		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）、续接原因（仅续接记录有）或撤销原因（仅撤销回执记录有）
46		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）或被撤销的原回执请求号（仅撤销回执记录有）
47		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接、撤销回执记录有；续接时为新批次号）
48		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
49		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
50		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
51		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
52		Incident string `json:"incident,omitempty"`
53		Note     string `json:"note,omitempty"`
54	}
55	
56	// Parcel 是一件包裹的台账信息。
57	type Parcel struct {
58		ID         string    `json:"id"`
59		Station    string    `json:"station"`    // 当前归属站点
60		Status     string    `json:"status"`     // 当前状态
61		Registered time.Time `json:"registered"` // 收件时间
62		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
63	}
64	
65	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
66	type HandoffResult struct {
67		Request    string    `json:"request"`
68		From       string    `json:"from"`
69		To         string    `json:"to"`
70		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
71		Time       time.Time `json:"time"`
72		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
73	}
74	
75	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
76	type ReturnResult struct {
77		Request string    `json:"request"` // 退回请求号
78		Handoff string    `json:"handoff"` // 被退回的原交接请求号
79		From    string    `json:"from"`    // 退回源站（原交接目的站）
80		To      string    `json:"to"`      // 退回目的站（原交接源站）
81		Reason  string    `json:"reason"`
82		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
83		Time    time.Time `json:"time"`
84	}
85	
86	// ReceiptEntry 是批次内一件包裹的当前回执记录（被新回执取代的已撤销条目由
87	// 台账级 Receipts 结果表与撤销记录共同保留）。
88	type ReceiptEntry struct {
89		Request string    `json:"request"`          // 回执请求号
90		Result  string    `json:"result"`           // 签收 | 失败
91		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
92		Time    time.Time `json:"time"`
93		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；撤销后该条不再计入有效回执。
94		RevokedBy string `json:"revokedBy,omitempty"`
95	}
96	
97	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
98	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
99	type BatchResult struct {
100		Batch    string                   `json:"batch"`
101		Station  string                   `json:"station"`  // 出发站
102		Courier  string                   `json:"courier"`  // 配送员
103		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
104		Time     time.Time                `json:"time"`     // 出站时间
105		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
106		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
107		AbortedBy string `json:"abortedBy,omitempty"`
108		// TransferredBy 为把该批次关闭为“已转交”的续接请求号（未转交为空）；
109		// 转交永久生效，与中止互斥，批次不得复用。
110		TransferredBy string `json:"transferredBy,omitempty"`
111		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
112		// 与创建本批次的续接请求号（普通出站批次为空）。
113		RelayedFrom  string `json:"relayedFrom,omitempty"`
114		RelayRequest string `json:"relayRequest,omitempty"`
115	}
116	
117	// Effective 返回批次当前有效（未撤销）的回执数量。
118	func (b *BatchResult) Effective() int {
119		n := 0
120		for _, e := range b.Receipts {
121			if e != nil && e.RevokedBy == "" {
122				n++
123			}
124		}
125		return n
126	}
127	
128	// Done 报告批次是否已完成（全部成员均有未撤销的有效回执）。
129	func (b *BatchResult) Done() bool { return b.Effective() == len(b.Parcels) }
130	
131	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
132	// 回执结果永久保留：即使之后被撤销，回执请求号也不删除、不释放。
133	type ReceiptResult struct {
134		Request string    `json:"request"` // 回执请求号
135		Batch   string    `json:"batch"`   // 所属配送批次号
136		Parcel  string    `json:"parcel"`  // 包裹编号
137		Result  string    `json:"result"`  // 签收 | 失败
138		Reason  string    `json:"reason,omitempty"`
139		Time    time.Time `json:"time"`
140		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；每条回执只能被撤销一次。
141		RevokedBy string `json:"revokedBy,omitempty"`
142	}
143	
144	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
145	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
146	type FreezeResult struct {
147		Incident string    `json:"incident"` // 异常单号
148		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
149		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
150		Reason   string    `json:"reason"`   // 清理后的冻结原因
151		Time     time.Time `json:"time"`     // 冻结时间
152		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
153		ReleasedBy string `json:"releasedBy,omitempty"`
154	}
155	
156	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
157	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
158	type UnfreezeResult struct {
159		Request  string    `json:"request"`  // 解除请求号
160		Incident string    `json:"incident"` // 被解除的异常单号
161		Parcel   string    `json:"parcel"`   // 对应包裹编号
162		Note     string    `json:"note"`     // 清理后的处理说明
163		Time     time.Time `json:"time"`     // 解除时间
164	}
165	
166	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
167	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
168	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
169	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
170	type AbortResult struct {
171		Request string    `json:"request"` // 中止请求号
172		Batch   string    `json:"batch"`   // 被中止的配送批次号
173		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
174		Reason  string    `json:"reason"`  // 清理后的中止原因
175		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
176		Time    time.Time `json:"time"`    // 中止时间
177	}
178	
179	// TransferResult 记录一次成功的配送途中整批续接，用于续接请求号去重与结果重放。
180	// 续接表示原配送员把原批次全部尚未回执的包裹在配送途中交给另一配送员：
181	// 新批次按原顺序接纳全部未回执件继续配送，包裹保持“配送中”及原站点，
182	// 原批次永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他
183	// 业务编号同名；失败的首次续接不占用请求号。
184	type TransferResult struct {
185		Request     string    `json:"request"`     // 续接请求号
186		FromBatch   string    `json:"fromBatch"`   // 原批次号
187		ToBatch     string    `json:"toBatch"`     // 新批次号
188		Station     string    `json:"station"`     // 出发站（沿用原批次）
189		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
190		ToCourier   string    `json:"toCourier"`   // 新配送员
191		Reason      string    `json:"reason"`      // 清理后的续接原因
192		Parcels     []string  `json:"parcels"`     // 首次转交集合（原批次未回执成员，按原成员顺序）
193		Time        time.Time `json:"time"`        // 接手时间
194	}
195	
196	// RevokeResult 记录一次成功的误录回执撤销，用于撤销请求号去重与结果重放。
197	// 撤销只更正台账：经核实包裹实际仍由原配送员配送，撤销错误的签收或失败登记，
198	// 不收回实物。原回执结果与轨迹永久保留并标记已撤销，回执请求号不删除也不释放。
199	// 撤销请求号独立去重，可与批次号、包裹号、回执请求号及其他业务编号同名；
200	// 失败的首次撤销不占用请求号。
201	type RevokeResult struct {
202		Request string    `json:"request"` // 撤销请求号
203		Receipt string    `json:"receipt"` // 被撤销的原回执请求号
204		Batch   string    `json:"batch"`   // 所属配送批次号（取自原回执，不可另选）
205		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
206		Reason  string    `json:"reason"`  // 清理后的撤销原因
207		Time    time.Time `json:"time"`    // 撤销时间
208	}
209	
210	// ShipmentResult 记录一次成功的站间发运，用于运输单号去重、结果重放与运输单查询。
211	// 发运表示整单包裹已离开源站、尚未到达目的站：整单转为“站间在途”，归属站点暂记
212	// 源站，成员按首次提交顺序保存，保存后不可修改。运输单号独立于已有各类编号，
213	// 接收后也不释放；失败的首次发运不占用运输单号。
214	type ShipmentResult struct {
215		Shipment string    `json:"shipment"` // 运输单号
216		From     string    `json:"from"`     // 源站
217		To       string    `json:"to"`       // 目的站
218		Parcels  []string  `json:"parcels"`  // 成员，按首次提交顺序
219		Time     time.Time `json:"time"`     // 发运时间
220		// ReceivedBy 为使该运输单达到全部接收的接收请求号（尚未全部接收为空）；
221		// 全部接收永久生效，运输单号不释放。分批到站时可能经历多次接收，
222		// 每次接收记录于接收结果表，是否全部接收按各次接收事实统计。
223		ReceivedBy string `json:"receivedBy,omitempty"`
224	}
225	
226	// ReceiveResult 记录一次成功的到站接收，用于接收请求号去重与结果重放。
227	// 接收表示运输单的一批成员已到达目的站：按发运保存顺序将本次成员改归目的站、
228	// 恢复在站；全部成员到齐后运输单永久标记为已接收。接收请求号与运输单号及已有
229	// 各类编号分属独立去重范围，允许同名；失败的首次接收不占用请求号。
230	type ReceiveResult struct {
231		Request  string    `json:"request"`  // 接收请求号
232		Shipment string    `json:"shipment"` // 被接收的运输单号
233		Station  string    `json:"station"`  // 接收站点（即运输单目的站）
234		Parcels  []string  `json:"parcels"`  // 本次接收的成员，按发运保存顺序
235		Time     time.Time `json:"time"`     // 接收时间
236		// Explicit 为 true 表示本次接收显式选择了包裹集合；false 表示不选成员、
237		// 接收当时全部尚未接收件（旧版整单接收记录没有该字段，按不选成员处理）。
238		Explicit bool `json:"explicit,omitempty"`
239	}
240	
241	// ledgerFile 是本地数据文件的磁盘结构。
242	type ledgerFile struct {
243		Version   int                        `json:"version"`
244		Parcels   map[string]*Parcel         `json:"parcels"`
245		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
246		Returns   map[string]*ReturnResult   `json:"returns"`
247		Batches   map[string]*BatchResult    `json:"batches"`
248		Receipts  map[string]*ReceiptResult  `json:"receipts"`
249		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
250		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
251		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
252		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
253		Revokes   map[string]*RevokeResult   `json:"revokes"`   // 以撤销请求号为键
254		Shipments map[string]*ShipmentResult `json:"shipments"` // 以运输单号为键（含已接收的运输单，永久保留）
255		Receives  map[string]*ReceiveResult  `json:"receives"`  // 以接收请求号为键
256	}
257	
258	// Store 是一个数据文件对应的包裹站点交接台账。
259	type Store struct {
260		path string
261		data ledgerFile
262	}
263	
264	var (
265		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
266		ErrCorrupt = errors.New("数据文件已损坏")
267		// ErrNotFound 表示包裹编号在台账中不存在。
268		ErrNotFound = errors.New("包裹不存在")
269	)
270	
271	// Open 打开（或在文件不存在时建立）一个本地台账。
272	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
273	func Open(path string) (*Store, error) {
274		s := &Store{path: path}
275		raw, err := os.ReadFile(path)
276		if err != nil {
277			if os.IsNotExist(err) {
278				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
279					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
280					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
281					Transfers: map[string]*TransferResult{}, Revokes: map[string]*RevokeResult{}, Shipments: map[string]*ShipmentResult{},
282					Receives: map[string]*ReceiveResult{}}
283				return s, nil
284			}
285			return nil, fmt.Errorf("读取数据文件失败: %w", err)
286		}
287		if len(bytes.TrimSpace(raw)) == 0 {
288			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
289		}
290		if err := json.Unmarshal(raw, &s.data); err != nil {
291			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
292		}
293		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
294			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
295		}
296		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort/revoke 相关字段：按空表处理，无需手工修改。
297		if s.data.Returns == nil {
298			s.data.Returns = map[string]*ReturnResult{}
299		}
300		if s.data.Batches == nil {
301			s.data.Batches = map[string]*BatchResult{}
302		}
303		if s.data.Receipts == nil {
304			s.data.Receipts = map[string]*ReceiptResult{}
305		}
306		if s.data.Freezes == nil {
307			s.data.Freezes = map[string]*FreezeResult{}
308		}
309		if s.data.Unfreezes == nil {
310			s.data.Unfreezes = map[string]*UnfreezeResult{}
311		}
312		if s.data.Aborts == nil {
313			s.data.Aborts = map[string]*AbortResult{}
314		}
315		if s.data.Transfers == nil {
316			s.data.Transfers = map[string]*TransferResult{}
317		}
318		if s.data.Revokes == nil {
319			s.data.Revokes = map[string]*RevokeResult{}
320		}
321		// 早期版本的数据文件没有 shipments/receives 字段：按空表处理，无需手工修改。
322		if s.data.Shipments == nil {
323			s.data.Shipments = map[string]*ShipmentResult{}
324		}
325		if s.data.Receives == nil {
326			s.data.Receives = map[string]*ReceiveResult{}
327		}
328		for _, b := range s.data.Batches {
329			if b != nil && b.Receipts == nil {
330				b.Receipts = map[string]*ReceiptEntry{}
331			}
332		}
333		if err := s.data.validate(); err != nil {
334			return nil, err
335		}
336		return s, nil
337	}
338	
339	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
340	func (l *ledgerFile) validate() error {
341		for id, p := range l.Parcels {
342			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
343				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
344			}
345			switch p.Status {
346			case statusInStation, statusDelivering, statusSigned, statusFrozen, statusInTransit:
347			default:
348				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
349			}
350			for i, e := range p.Trail {
351				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
352					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
353				}
354				if e.Op == "退回" {
355					if e.Request == "" || e.Reason == "" || e.From == "" {
356						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
357					}
358					if _, ok := l.Handoffs[e.RefRequest]; !ok {
359						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
360					}
361				}
362				if e.Op == "出站" {
363					if e.Batch == "" || e.Courier == "" {
364						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
365					}
366					if _, ok := l.Batches[e.Batch]; !ok {
367						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
368					}
369				}
370				if e.Op == "回执" {
371					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
372						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
373					}
374					if e.Result == resultFailed && e.Reason == "" {
375						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
376					}
377					if _, ok := l.Batches[e.Batch]; !ok {
378						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
379					}
380				}
381				if e.Op == "撤销回执" {
382					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
383						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
384					}
385					b, ok := l.Batches[e.Batch]
386					if !ok || b == nil {
387						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
388					}
389					if e.Station != b.Station {
390						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
391							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
392					}
393					rv, ok := l.Revokes[e.Request]
394					if !ok || rv == nil {
395						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
396					}
397					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
398						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
399					}
400				}
401				if e.Op == "收回" {
402					if e.Batch == "" || e.Request == "" || e.Reason == "" {
403						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
404					}
405					a, ok := l.Aborts[e.Request]
406					if !ok || a == nil {
407						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
408					}
409					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
410						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
411					}
412					inAbort := false
413					for _, pid := range a.Parcels {
414						if pid == id {
415							inAbort = true
416							break
417						}
418					}
419					if !inAbort {
420						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
421					}
422				}
423				if e.Op == "续接" {
424					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
425						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
426					}
427					t, ok := l.Transfers[e.Request]
428					if !ok || t == nil {
429						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
430					}
431					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
432						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
433						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
434					}
435					inTransfer := false
436					for _, pid := range t.Parcels {
437						if pid == id {
438							inTransfer = true
439							break
440						}
441					}
442					if !inTransfer {
443						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
444					}
445				}
446				if e.Op == "发运" {
447					if e.Shipment == "" || e.From == "" || e.To == "" {
448						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹缺少运输单号、源站或目的站", ErrCorrupt, id, i+1)
449					}
450					sh, ok := l.Shipments[e.Shipment]
451					if !ok || sh == nil {
452						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
453					}
454					if sh.From != e.From || sh.To != e.To || e.Station != e.From || !sh.Time.Equal(e.Time) {
455						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹与运输单 %q 记录不一致", ErrCorrupt, id, i+1, e.Shipment)
456					}
457					inShipment := false
458					for _, pid := range sh.Parcels {
459						if pid == id {
460							inShipment = true
461							break
462						}
463					}
464					if !inShipment {
465						return fmt.Errorf("%w: 包裹 %q 第 %d 条发运轨迹不在运输单 %q 的成员集合中", ErrCorrupt, id, i+1, e.Shipment)
466					}
467				}
468				if e.Op == "接收" {
469					if e.Shipment == "" || e.Request == "" || e.From == "" || e.To == "" {
470						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹缺少运输单号、接收请求号、源站或目的站", ErrCorrupt, id, i+1)
471					}
472					rv, ok := l.Receives[e.Request]
473					if !ok || rv == nil {
474						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的接收请求 %q", ErrCorrupt, id, i+1, e.Request)
475					}
476					if rv.Shipment != e.Shipment || rv.Station != e.Station || e.Station != e.To || !rv.Time.Equal(e.Time) {
477						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹与接收请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
478					}
479					sh, ok := l.Shipments[e.Shipment]
480					if !ok || sh == nil {
481						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹引用了不存在的运输单 %q", ErrCorrupt, id, i+1, e.Shipment)
482					}
483					if sh.From != e.From || sh.To != e.To {
484						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的源站或目的站与运输单 %q 记录（%q -> %q）不一致",
485							ErrCorrupt, id, i+1, e.Shipment, sh.From, sh.To)
486					}
487					inReceive := false
488					for _, pid := range rv.Parcels {
489						if pid == id {
490							inReceive = true
491							break
492						}
493					}
494					if !inReceive {
495						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹不在接收请求 %q 的成员集合中", ErrCorrupt, id, i+1, e.Request)
496					}
497				}
498				if e.Op == "冻结" {
499					if e.Incident == "" || e.Reason == "" {
500						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
501					}
502					f, ok := l.Freezes[e.Incident]
503					if !ok || f == nil {
504						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
505					}
506					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
507						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
508					}
509				}
510				if e.Op == "解除冻结" {
511					if e.Incident == "" || e.Request == "" || e.Note == "" {
512						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
513					}
514					f, ok := l.Freezes[e.Incident]
515					if !ok || f == nil {
516						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
517					}
518					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
519						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
520					}
521					u, ok := l.Unfreezes[e.Request]
522					if !ok || u == nil || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
523						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
524					}
525				}
526			}
527		}
528		// 站间运输生命周期：按每件轨迹的保存顺序（不按发生时间排序）核对发运与接收的
529		// 配对关系。每张运输单的成员恰有一次对应发运；已接收时恰有一次对应接收且位于
530		// 发运之后；发运后到接收前不得出现其他作业轨迹；未接收时不得有接收记录，
531		// 发运必须是最后一条轨迹。
532		for id, p := range l.Parcels {
533			shipped := make(map[string]bool) // 该包裹轨迹中已出现发运的运输单号
534			var open string                  // 已发运、尚未在轨迹中接收的在途运输单号
535			for i, e := range p.Trail {
536				if open != "" && e.Op != "接收" {
537					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹（%s）出现在运输单 %q 发运之后、接收之前，在途期间不得有其他作业轨迹",
538						ErrCorrupt, id, i+1, e.Op, open)
539				}
540				switch e.Op {
541				case "发运":
542					if shipped[e.Shipment] {
543						return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹重复发运运输单 %q，每张运输单的成员恰有一次对应发运",
544							ErrCorrupt, id, i+1, e.Shipment)
545					}
546					shipped[e.Shipment] = true
547					open = e.Shipment
548				case "接收":
549					if open == "" {
550						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹（运输单 %q）位于对应发运之前或缺少对应发运",
551							ErrCorrupt, id, i+1, e.Shipment)
552					}
553					if e.Shipment != open {
554						return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的运输单 %q 与当前在途运输单 %q 不匹配",
555							ErrCorrupt, id, i+1, e.Shipment, open)
556					}
557					open = ""
558				}
559			}
560			if open != "" {
561				sh := l.Shipments[open] // 发运轨迹校验已保证运输单存在且非空
562				if sh.ReceivedBy != "" {
563					return fmt.Errorf("%w: 包裹 %q 的运输单 %q 已接收（接收请求号 %q），但轨迹缺少对应的接收记录",
564						ErrCorrupt, id, open, sh.ReceivedBy)
565				}
566			}
567		}
568		// 当前归属与状态必须由轨迹记录形成：按保存顺序的最后一条轨迹推导应有的归属
569		// 站点与状态，与台账当前值不一致即存在无对应记录的站点或状态改变。接收后的
570		// 合法后续流转（交接、再次发运、回执及其撤销、收回、续接、冻结与解除）会
571		// 产生新的末条轨迹，按新轨迹校验，不因历史接收而把成员固定在目的站。
572		for id, p := range l.Parcels {
573			last := p.Trail[len(p.Trail)-1]
574			var want string
575			switch last.Op {
576			case "收件", "交接", "退回", "收回", "接收", "解除冻结":
577				want = statusInStation
578			case "出站", "续接", "撤销回执":
579				want = statusDelivering
580			case "回执":
581				if last.Result == resultSigned {
582					want = statusSigned
583				} else {
584					want = statusInStation
585				}
586			case "冻结":
587				want = statusFrozen
588			case "发运":
589				want = statusInTransit
590			default:
591				continue // 未知操作不参与推导（逐条校验已兜底）
592			}
593			if p.Station != last.Station || p.Status != want {
594				return fmt.Errorf("%w: 包裹 %q 当前归属 %q、状态 %q 与最后一条轨迹（%s，站点 %q）应形成的归属与状态 %q、%q 不一致",
595					ErrCorrupt, id, p.Station, p.Status, last.Op, last.Station, last.Station, want)
596			}
597		}
598		for req, h := range l.Handoffs {
599			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
600				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
601			}
602			for _, id := range h.Parcels {
603				if _, ok := l.Parcels[id]; !ok {
604					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
605				}
606			}
607			if h.ReturnedBy != "" {
608				r, ok := l.Returns[h.ReturnedBy]
609				if !ok || r == nil || r.Handoff != req {
610					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
611				}
612			}
613		}
614		for req, r := range l.Returns {
615			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
616				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
617				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
618			}
619			h, ok := l.Handoffs[r.Handoff]
620			if !ok || h == nil {
621				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
622			}
623			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
624				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
625			}
626			for _, id := range r.Parcels {
627				if _, ok := l.Parcels[id]; !ok {
628					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
629				}
630			}
631		}
632		for id, b := range l.Batches {
633			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
634				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
635			}
636			seen := make(map[string]bool, len(b.Parcels))
637			for _, pid := range b.Parcels {
638				if seen[pid] {
639					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
640				}
641				seen[pid] = true
642				if _, ok := l.Parcels[pid]; !ok {
643					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
644				}
645			}
646			for pid, e := range b.Receipts {
647				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
648					(e.Result != resultSigned && e.Result != resultFailed) ||
649					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
650					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
651				}
652				rc, ok := l.Receipts[e.Request]
653				if !ok || rc == nil || rc.Batch != id || rc.Parcel != pid {
654					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
655				}
656				if e.RevokedBy != rc.RevokedBy {
657					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执条目与回执请求号 %q 的撤销标记不一致", ErrCorrupt, id, pid, e.Request)
658				}
659			}
660			if b.AbortedBy != "" {
661				a, ok := l.Aborts[b.AbortedBy]
662				if !ok || a == nil || a.Batch != id {
663					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
664				}
665			}
666			if b.TransferredBy != "" {
667				if b.AbortedBy != "" {
668					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
669				}
670				t, ok := l.Transfers[b.TransferredBy]
671				if !ok || t == nil || t.FromBatch != id {
672					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
673				}
674			}
675			if b.RelayedFrom != "" {
676				t, ok := l.Transfers[b.RelayRequest]
677				if !ok || t == nil || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
678					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
679						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
680				}
681			} else if b.RelayRequest != "" {
682				return fmt.Errorf("%w: 批次 %q 标记了续接请求号 %q 但缺少来源批次", ErrCorrupt, id, b.RelayRequest)
683			}
684		}
685		for req, rc := range l.Receipts {
686			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
687				(rc.Result != resultSigned && rc.Result != resultFailed) ||
688				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
689				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
690			}
691			b, ok := l.Batches[rc.Batch]
692			if !ok || b == nil {
693				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
694			}
695			// 每件包裹的当前回执条目一旦建立只会被新回执取代、不会删除，
696			// 因此该件在批次内必须始终有一条回执条目。
697			e, cur := b.Receipts[rc.Parcel]
698			if !cur {
699				return fmt.Errorf("%w: 回执请求号 %q 在批次 %q 中缺少包裹 %q 的回执条目", ErrCorrupt, req, rc.Batch, rc.Parcel)
700			}
701			if rc.RevokedBy == "" {
702				// 未撤销回执必须仍是该件在该批次的当前有效回执。
703				if e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != "" {
704					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
705				}
706				continue
707			}
708			// 已撤销回执：撤销关联必须存在且回指该回执。
709			rv, ok := l.Revokes[rc.RevokedBy]
710			if !ok || rv == nil || rv.Receipt != req {
711				return fmt.Errorf("%w: 回执请求号 %q 标记的撤销请求号 %q 无法对应", ErrCorrupt, req, rc.RevokedBy)
712			}
713			if e.Request == req {
714				// 该件之后未重新回执：批次内条目必须同内容并同样标记撤销。
715				if e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != rc.RevokedBy {
716					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
717				}
718			}
719			// 该件之后已用新请求号重新回执：当前条目属于新回执，由其自身校验。
720		}
721		// 撤销：每条撤销必须对应一条已撤销回执，批次、包裹一致，且包裹轨迹中有
722		// 与该撤销请求一致的撤销回执记录；撤销关联缺失或不一致即损坏。
723		for req, rv := range l.Revokes {
724			if rv == nil || req != rv.Request || rv.Receipt == "" || rv.Batch == "" || rv.Parcel == "" ||
725				rv.Reason == "" || rv.Time.IsZero() {
726				return fmt.Errorf("%w: 撤销请求号 %q 的撤销结果不完整", ErrCorrupt, req)
727			}
728			rc, ok := l.Receipts[rv.Receipt]
729			if !ok || rc == nil {
730				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的原回执 %q", ErrCorrupt, req, rv.Receipt)
731			}
732			if rc.RevokedBy != req {
733				return fmt.Errorf("%w: 撤销请求号 %q 与原回执 %q 的撤销标记不一致", ErrCorrupt, req, rv.Receipt)
734			}
735			if rc.Batch != rv.Batch || rc.Parcel != rv.Parcel {
736				return fmt.Errorf("%w: 撤销请求号 %q 的批次或包裹与原回执 %q 不一致", ErrCorrupt, req, rv.Receipt)
737			}
738			p, ok := l.Parcels[rv.Parcel]
739			if !ok {
740				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, rv.Parcel)
741			}
742			found := false
743			for _, e := range p.Trail {
744				if e.Op == "撤销回执" && e.Request == req {
745					found = true
746					break
747				}
748			}
749			if !found {
750				return fmt.Errorf("%w: 撤销请求号 %q 的包裹 %q 缺少对应的撤销回执轨迹", ErrCorrupt, req, rv.Parcel)
751			}
752		}
753		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序，已撤销回执不计入
754		// 有效回执），且每件收回包裹的轨迹中都有与该中止请求一致的收回记录；
755		// 中止记录与收回轨迹不一致即损坏。
756		for req, a := range l.Aborts {
757			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
758				len(a.Parcels) == 0 || a.Time.IsZero() {
759				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
760			}
761			b, ok := l.Batches[a.Batch]
762			if !ok || b == nil {
763				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
764			}
765			if b.AbortedBy != req {
766				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
767			}
768			if a.Station != b.Station {
769				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
770			}
771			expect := make([]string, 0, len(b.Parcels))
772			for _, pid := range b.Parcels {
773				if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
774					expect = append(expect, pid)
775				}
776			}
777			if len(expect) != len(a.Parcels) {
778				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
779			}
780			for i := range expect {
781				if expect[i] != a.Parcels[i] {
782					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
783				}
784			}
785			for _, pid := range a.Parcels {
786				p, ok := l.Parcels[pid]
787				if !ok {
788					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
789				}
790				found := false
791				for _, e := range p.Trail {
792					if e.Op == "收回" && e.Request == req {
793						found = true
794						break
795					}
796				}
797				if !found {
798					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
799				}
800			}
801		}
802		// 续接：转交集合必须恰为原批次的未回执成员（按原成员顺序），新批次必须由该续接
803		// 创建且成员、站点、配送员、接手时间与之一致；每件转交包裹的轨迹中都有与该
804		// 续接请求一致的续接记录；续接记录与批次及轨迹不一致即损坏。
805		for req, t := range l.Transfers {
806			if t == nil || req != t.Request || t.FromBatch == "" || t.ToBatch == "" || t.Station == "" ||
807				t.FromCourier == "" || t.ToCourier == "" || t.FromCourier == t.ToCourier ||
808				t.Reason == "" || len(t.Parcels) == 0 || t.Time.IsZero() {
809				return fmt.Errorf("%w: 续接请求号 %q 的续接结果不完整", ErrCorrupt, req)
810			}
811			fb, ok := l.Batches[t.FromBatch]
812			if !ok || fb == nil {
813				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的原批次 %q", ErrCorrupt, req, t.FromBatch)
814			}
815			if fb.TransferredBy != req {
816				return fmt.Errorf("%w: 续接请求号 %q 与原批次 %q 的转交标记不一致", ErrCorrupt, req, t.FromBatch)
817			}
818			if fb.Station != t.Station || fb.Courier != t.FromCourier {
819				return fmt.Errorf("%w: 续接请求号 %q 的站点或原配送员与原批次 %q 不一致", ErrCorrupt, req, t.FromBatch)
820			}
821			nb, ok := l.Batches[t.ToBatch]
822			if !ok || nb == nil {
823				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的新批次 %q", ErrCorrupt, req, t.ToBatch)
824			}
825			if nb.RelayedFrom != t.FromBatch || nb.RelayRequest != req {
826				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的来源标记不一致", ErrCorrupt, req, t.ToBatch)
827			}
828			if nb.Station != t.Station || nb.Courier != t.ToCourier || !nb.Time.Equal(t.Time) {
829				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的站点、配送员或接手时间不一致", ErrCorrupt, req, t.ToBatch)
830			}
831			expect := make([]string, 0, len(fb.Parcels))
832			for _, pid := range fb.Parcels {
833				if e, done := fb.Receipts[pid]; !done || e.RevokedBy != "" {
834					expect = append(expect, pid)
835				}
836			}
837			if !sameOrder(expect, t.Parcels) || !sameOrder(t.Parcels, nb.Parcels) {
838				return fmt.Errorf("%w: 续接请求号 %q 的转交集合与原批次 %q 的未回执成员或新批次 %q 的成员不一致",
839					ErrCorrupt, req, t.FromBatch, t.ToBatch)
840			}
841			for _, pid := range t.Parcels {
842				p, ok := l.Parcels[pid]
843				if !ok {
844					return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
845				}
846				found := false
847				for _, e := range p.Trail {
848					if e.Op == "续接" && e.Request == req {
849						found = true
850						break
851					}
852				}
853				if !found {
854					return fmt.Errorf("%w: 续接请求号 %q 的转交包裹 %q 缺少对应的续接轨迹", ErrCorrupt, req, pid)
855				}
856			}
857		}
858		// 发运：成员必须非空、不重复且都已登记，每件成员的轨迹中都有与该运输单一致的
859		// 发运记录；尚未接收的成员必须仍归该单在途（状态为站间在途、归属源站），已接收
860		// 成员的现状不限（其后续流转不影响接收事实）；一件包裹同时只能属于一张运输单的
861		// 未接收成员。全部接收标记必须与各次接收事实一致：全部成员均已接收时恰有
862		// 完成接收的请求号，未全部接收时不得标记。关联缺失或矛盾即损坏。
863		receivedByShipment := make(map[string]map[string]bool) // 运输单号 -> 已接收成员集合
864		for _, r := range l.Receives {
865			if r == nil {
866				continue // 空关联由接收结果校验统一报错
867			}
868			set := receivedByShipment[r.Shipment]
869			if set == nil {
870				set = make(map[string]bool)
871				receivedByShipment[r.Shipment] = set
872			}
873			for _, pid := range r.Parcels {
874				set[pid] = true
875			}
876		}
877		inTransitCount := make(map[string]int) // 包裹 -> 以它为未接收成员的运输单数
878		for no, sh := range l.Shipments {
879			if sh == nil || no != sh.Shipment || sh.From == "" || sh.To == "" || sh.From == sh.To ||
880				len(sh.Parcels) == 0 || sh.Time.IsZero() {
881				return fmt.Errorf("%w: 运输单号 %q 的发运结果不完整", ErrCorrupt, no)
882			}
883			seen := make(map[string]bool, len(sh.Parcels))
884			for _, pid := range sh.Parcels {
885				if seen[pid] {
886					return fmt.Errorf("%w: 运输单 %q 的成员 %q 重复", ErrCorrupt, no, pid)
887				}
888				seen[pid] = true
889				p, ok := l.Parcels[pid]
890				if !ok {
891					return fmt.Errorf("%w: 运输单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, pid)
892				}
893				found := false
894				for _, e := range p.Trail {
895					if e.Op == "发运" && e.Shipment == no {
896						found = true
897						break
898					}
899				}
900				if !found {
901					return fmt.Errorf("%w: 运输单 %q 的成员包裹 %q 缺少对应的发运轨迹", ErrCorrupt, no, pid)
902				}
903			}
904			received := receivedByShipment[no]
905			receivedCount := 0
906			for _, pid := range sh.Parcels {
907				if received[pid] {
908					receivedCount++
909				}
910			}
911			if sh.ReceivedBy != "" {
912				r, ok := l.Receives[sh.ReceivedBy]
913				if !ok || r == nil || r.Shipment != no {
914					return fmt.Errorf("%w: 运输单 %q 标记的接收请求号 %q 无法对应", ErrCorrupt, no, sh.ReceivedBy)
915				}
916				if receivedCount != len(sh.Parcels) {
917					return fmt.Errorf("%w: 运输单 %q 标记已全部接收（接收请求号 %q），但按接收事实仍有成员未接收",
918						ErrCorrupt, no, sh.ReceivedBy)
919				}
920			} else if receivedCount == len(sh.Parcels) {
921				return fmt.Errorf("%w: 运输单 %q 的全部成员均已接收，但缺少全部接收标记", ErrCorrupt, no)
922			}
923			for _, pid := range sh.Parcels {
924				if received[pid] {
925					continue // 已收件的现状不限：后续交接、冻结、配送或再次发运不妨碍余件接收
926				}
927				p := l.Parcels[pid]
928				inTransitCount[pid]++
929				if p.Status != statusInTransit || p.Station != sh.From {
930					return fmt.Errorf("%w: 运输单 %q 的成员包裹 %q 尚未接收，但当前归属 %q、状态 %q，不在该单在途",
931						ErrCorrupt, no, pid, p.Station, p.Status)
932				}
933			}
934		}
935		for id, p := range l.Parcels {
936			if p.Status == statusInTransit && inTransitCount[id] != 1 {
937				return fmt.Errorf("%w: 包裹 %q 当前为站间在途，但未接收运输单数为 %d，应恰好属于一张运输单的未接收成员",
938					ErrCorrupt, id, inTransitCount[id])
939			}
940		}
941		// 接收：接收站点必须等于运输单目的站，成员必须非空、不重复、均属原单且按发运
942		// 保存顺序排列；同一运输单各次接收的成员不得重叠（同单同件只能接收一次）；
943		// 每件成员的轨迹中都有与该接收请求一致的接收记录。关联缺失、同单同件重复
944		// 接收或与轨迹矛盾即损坏。
945		receiveSeen := make(map[string]map[string]string) // 运输单号 -> 包裹 -> 接收请求号
946		for req, r := range l.Receives {
947			if r == nil || req != r.Request || r.Shipment == "" || r.Station == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
948				return fmt.Errorf("%w: 接收请求号 %q 的接收结果不完整", ErrCorrupt, req)
949			}
950			sh, ok := l.Shipments[r.Shipment]
951			if !ok || sh == nil {
952				return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的运输单 %q", ErrCorrupt, req, r.Shipment)
953			}
954			if r.Station != sh.To {
955				return fmt.Errorf("%w: 接收请求号 %q 的接收站点 %q 与运输单 %q 目的站 %q 不一致", ErrCorrupt, req, r.Station, r.Shipment, sh.To)
956			}
957			member := make(map[string]bool, len(sh.Parcels))
958			for _, pid := range sh.Parcels {
959				member[pid] = true
960			}
961			seen := make(map[string]bool, len(r.Parcels))
962			pos := 0 // 成员必须按发运保存顺序排列：在 sh.Parcels 中的位置严格递增
963			for _, pid := range r.Parcels {
964				if !member[pid] {
965					return fmt.Errorf("%w: 接收请求号 %q 的包裹 %q 不属于运输单 %q", ErrCorrupt, req, pid, r.Shipment)
966				}
967				if seen[pid] {
968					return fmt.Errorf("%w: 接收请求号 %q 的成员 %q 重复", ErrCorrupt, req, pid)
969				}
970				seen[pid] = true
971				at := -1
972				for i := pos; i < len(sh.Parcels); i++ {
973					if sh.Parcels[i] == pid {
974						at = i
975						break
976					}
977				}
978				if at < 0 {
979					return fmt.Errorf("%w: 接收请求号 %q 的成员顺序与运输单 %q 的发运保存顺序不一致", ErrCorrupt, req, r.Shipment)
980				}
981				pos = at + 1
982				if prev, dup := receiveSeen[r.Shipment][pid]; dup {
983					return fmt.Errorf("%w: 包裹 %q 在运输单 %q 下被接收请求 %q 与 %q 重复接收，同单同件只能接收一次",
984						ErrCorrupt, pid, r.Shipment, prev, req)
985				}
986				if receiveSeen[r.Shipment] == nil {
987					receiveSeen[r.Shipment] = make(map[string]string)
988				}
989				receiveSeen[r.Shipment][pid] = req
990			}
991			for _, pid := range r.Parcels {
992				p, ok := l.Parcels[pid]
993				if !ok {
994					return fmt.Errorf("%w: 接收请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
995				}
996				found := false
997				for _, e := range p.Trail {
998					if e.Op == "接收" && e.Request == req {
999						found = true
1000						break
1001					}
1002				}
1003				if !found {
1004					return fmt.Errorf("%w: 接收请求号 %q 的成员包裹 %q 缺少对应的接收轨迹", ErrCorrupt, req, pid)
1005				}
1006			}
1007		}
1008		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
1009		// 再核对两张结果表与包裹当前状态的对应关系。
1010		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
1011		for id, p := range l.Parcels {
1012			var open string
1013			for i, e := range p.Trail {
1014				switch e.Op {
1015				case "冻结":
1016					if open != "" {
1017						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
1018							ErrCorrupt, id, i+1, open)
1019					}
1020					open = e.Incident
1021				case "解除冻结":
1022					if open != e.Incident {
1023						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
1024							ErrCorrupt, id, i+1, e.Incident, open)
1025					}
1026					open = ""
1027				}
1028			}
1029			if p.Status == statusFrozen && open == "" {
1030				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
1031			}
1032			if p.Status != statusFrozen && open != "" {
1033				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
1034			}
1035			if open != "" {
1036				openIncident[id] = open
1037			}
1038		}
1039		for no, f := range l.Freezes {
1040			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
1041				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
1042			}
1043			p, ok := l.Parcels[f.Parcel]
1044			if !ok {
1045				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
1046			}
1047			if f.ReleasedBy == "" && p.Station != f.Station {
1048				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
1049					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
1050			}
1051			if f.ReleasedBy != "" {
1052				u, ok := l.Unfreezes[f.ReleasedBy]
1053				if !ok || u == nil || u.Incident != no || u.Parcel != f.Parcel {
1054					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
1055				}
1056			}
1057		}
1058		activeByParcel := make(map[string]string)
1059		for req, u := range l.Unfreezes {
1060			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
1061				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
1062			}
1063			f, ok := l.Freezes[u.Incident]
1064			if !ok || f == nil {
1065				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
1066			}
1067			if f.Parcel != u.Parcel {
1068				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
1069			}
1070			if f.ReleasedBy != req {
1071				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
1072			}
1073		}
1074		for no, f := range l.Freezes {
1075			if f.ReleasedBy != "" {
1076				continue
1077			}
1078			if other, dup := activeByParcel[f.Parcel]; dup {
1079				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
1080			}
1081			activeByParcel[f.Parcel] = no
1082			if openIncident[f.Parcel] != no {
1083				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
1084					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
1085			}
1086			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
1087				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
1088			}
1089		}
1090		return nil
1091	}
