2015			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
2016				moved = append(moved, pid)
2017			}
2018		}
2019		if len(moved) == 0 {
2020			return nil, false, fmt.Errorf("续接失败：批次 %q 没有未回执成员，不能续接", fromBatch)
2021		}
