2023		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
2024		for _, pid := range moved {
2025			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
2026			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
2027				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批续接未执行",
2028					pid, p.Station, p.Status, fromBatch, b.Station)
2029			}
2030		}
2031	
2032		res = &TransferResult{
2033			Request:     request,
2034			FromBatch:   fromBatch,
2035			ToBatch:     toBatch,
2036			Station:     b.Station,
2037			FromCourier: b.Courier,
2038			ToCourier:   courier,
2039			Reason:      reason,
2040			Parcels:     append([]string(nil), moved...),
2041			Time:        now,
2042		}
2043		s.data.Transfers[request] = res
2044		s.data.Batches[toBatch] = &BatchResult{
2045			Batch:        toBatch,
2046			Station:      b.Station,
2047			Courier:      courier,
2048			Parcels:      append([]string(nil), moved...),
2049			Time:         now,
2050			Receipts:     map[string]*ReceiptEntry{},
2051			RelayedFrom:  fromBatch,
2052			RelayRequest: request,
2053		}
2054		b.TransferredBy = request
2055	
2056		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
2057		prev := make(map[string][]Event, len(moved))
2058		for _, pid := range moved {
2059			p := s.data.Parcels[pid]
2060			prev[pid] = append([]Event(nil), p.Trail...)
2061			p.Trail = append(p.Trail, Event{
2062				Op:        "续接",
2063				Station:   b.Station,
2064				Batch:     toBatch,
2065				FromBatch: fromBatch,
2066				Courier:   courier,
2067				Request:   request,
2068				Reason:    reason,
2069				Time:      now,
2070			})
2071		}
2072	
2073		if err := s.save(); err != nil {
2074			delete(s.data.Transfers, request)
2075			delete(s.data.Batches, toBatch)
2076			b.TransferredBy = ""
2077			for pid, old := range prev {
2078				s.data.Parcels[pid].Trail = old
2079			}
2080			return nil, false, err
2081		}
2082		return res, false, nil
2083	}
