2099	// Ship 提交一次站间发运：整单包裹离开源站、尚未到达目的站。
2100	//
2101	// 首次发运：每件包裹必须已登记、当前归属源站且状态为在站；任一不满足则整单拒绝，
2102	// 不作任何改动（在途、配送中、已签收或已冻结的包裹均不满足）。全部满足时整单转为
2103	// “站间在途”（归属站点暂记源站），每件追加一条含运输单号、两站和时间的发运记录；
2104	// 成员按首次提交顺序保存，保存后不可修改。每件包裹同时最多属于一张未接收运输单。
2105	// 发运算新的流转：发运后不能退回此前的旧交接；运输单不是交接，不能作为退回的原交接。
2106	// 运输单号独立于已有各类编号，接收后也不释放：相同运输单号且源站、目的站、包裹集合
2107	// 相同（集合顺序无关），直接返回首次成员顺序与发运时间，replayed 为 true，不检查现状、
2108	// 不追加轨迹、不改写台账；运输单号相同但内容不同报冲突；失败的首次发运不占用运输单号。
2109	func (s *Store) Ship(shipment, from, to string, parcels []string, now time.Time) (res *ShipmentResult, replayed bool, err error) {
2110		if saved, ok := s.data.Shipments[shipment]; ok {
2111			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
2112				return saved, true, nil
2113			}
2114			return nil, false, fmt.Errorf("运输单号 %q 已用于一次不同的发运（源站=%q 目的站=%q），内容冲突", shipment, saved.From, saved.To)
2115		}
2116	
2117		// 首次发运：先做全部校验，任何一件不满足都整单拒绝。
2118		for _, id := range parcels {
2119			p, ok := s.data.Parcels[id]
2120			if !ok {
2121				return nil, false, fmt.Errorf("发运失败：包裹 %q 未登记，整单发运未执行", id)
2122			}
2123			if p.Station != from {
2124				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前归属 %q，不在源站 %q，整单发运未执行", id, p.Station, from)
2125			}
2126			if p.Status != statusInStation {
2127				return nil, false, fmt.Errorf("发运失败：包裹 %q 当前状态为 %q，不是在站，整单发运未执行", id, p.Status)
2128			}
2129		}
2130	
2131		res = &ShipmentResult{
2132			Shipment: shipment,
2133			From:     from,
2134			To:       to,
2135			Parcels:  append([]string(nil), parcels...),
2136			Time:     now,
2137		}
2138		s.data.Shipments[shipment] = res
2139	
2140		// 记录旧值，落盘失败时整体回滚。
2141		prev := make(map[string]struct {
2142			status string
2143			trail  []Event
2144		}, len(parcels))
2145		for _, id := range parcels {
2146			p := s.data.Parcels[id]
2147			prev[id] = struct {
2148				status string
2149				trail  []Event
2150			}{p.Status, append([]Event(nil), p.Trail...)}
2151			p.Status = statusInTransit // 归属站点暂记源站，整单转为站间在途
2152			p.Trail = append(p.Trail, Event{
2153				Op:       "发运",
2154				Station:  from,
2155				From:     from,
2156				To:       to,
2157				Shipment: shipment,
2158				Time:     now,
2159			})
2160		}
2161	
2162		if err := s.save(); err != nil {
2163			delete(s.data.Shipments, shipment)
2164			for id, old := range prev {
2165				p := s.data.Parcels[id]
2166				p.Status = old.status
2167				p.Trail = old.trail
2168			}
2169			return nil, false, err
2170		}
2171		return res, false, nil
2172	}
