2174	// Receive 提交一次到站接收：运输单的部分或全部未到成员到达目的站。
2175	// parcels 为 nil 表示不选成员，接收当时全部尚未接收件；非 nil 为显式选择的
2176	// 非空、不重复集合（由调用方清洗）。
2177	//
2178	// 首次接收：运输单必须存在，接收站点必须等于运输单目的站，本次至少接收一件。
2179	// 显式集合的每件选中件都必须属于原单、尚未接收，且仍在源站归该单在途；
2180	// 不选成员时本次集合为当时的全部尚未接收件。任一不满足则整次拒绝，不作任何改动。
2181	// 已收件不再检查接收条件也不变更，其后续交接、冻结、配送或再次发运不妨碍余件接收。
2182	// 成功时按发运保存顺序将本次成员改归目的站、恢复“在站”，各追加一条含运输单号、
2183	// 两站、接收请求号和时间的接收记录；全部成员到齐后运输单永久标记为已接收，
2184	// 随后可继续在站作业。接收算新的流转：接收后不能退回此前的旧交接。
2185	// 两种选择方式共用接收请求号去重范围，与运输单号及已有各类编号独立，允许同名：
2186	// 相同接收请求号且运输单、接收站点、选择方式相同（显式集合换序无关），直接返回
2187	// 首次接收集合与时间，replayed 为 true，不检查现状、不重算余件、不追加轨迹、
2188	// 不改写台账（全部接收及后续流转后仍成立）；请求号相同但运输单、接收站点、
2189	// 选择方式或显式集合不同报冲突；全部接收后新请求拒绝；失败的首次接收不占用请求号。
2190	func (s *Store) Receive(request, shipment, station string, parcels []string, now time.Time) (res *ReceiveResult, replayed bool, err error) {
2191		explicit := parcels != nil
2192		if saved, ok := s.data.Receives[request]; ok {
2193			if saved.Shipment == shipment && saved.Station == station && saved.Explicit == explicit &&
2194				(!explicit || sameSet(saved.Parcels, parcels)) {
2195				return saved, true, nil
2196			}
2197			return nil, false, fmt.Errorf("接收请求号 %q 已用于一次不同的接收（运输单=%q 接收站点=%q），内容冲突",
2198				request, saved.Shipment, saved.Station)
2199		}
2200	
2201		sh, ok := s.data.Shipments[shipment]
2202		if !ok {
2203			return nil, false, fmt.Errorf("接收失败：运输单号 %q 不存在", shipment)
2204		}
2205		if station != sh.To {
2206			return nil, false, fmt.Errorf("接收失败：接收站点 %q 不是运输单 %q 的目的站 %q，本次接收未执行", station, shipment, sh.To)
2207		}
2208	
2209		received := s.receivedUnder(shipment)
2210		var members []string // 本次接收集合，按发运保存顺序
2211		if explicit {
2212			if len(parcels) == 0 {
2213				return nil, false, fmt.Errorf("接收失败：显式选择的包裹集合不可为空，本次接收未执行")
2214			}
2215			want := make(map[string]bool, len(parcels))
2216			for _, pid := range parcels {
2217				want[pid] = true
2218			}
2219			// 先做全部校验：选中件均属原单、尚未接收且仍归该单在途，任一不符整次拒绝。
2220			for _, pid := range parcels {
2221				member := false
2222				for _, mid := range sh.Parcels {
2223					if mid == pid {
2224						member = true
2225						break
2226					}
2227				}
2228				if !member {
2229					return nil, false, fmt.Errorf("接收失败：包裹 %q 不属于运输单 %q，本次接收未执行", pid, shipment)
2230				}
2231				if received[pid] {
2232					return nil, false, fmt.Errorf("接收失败：包裹 %q 已在运输单 %q 下接收，不能重复接收，本次接收未执行", pid, shipment)
2233				}
2234				p := s.data.Parcels[pid] // 运输单成员必已登记（载入校验保证）
2235				if p.Status != statusInTransit || p.Station != sh.From {
2236					return nil, false, fmt.Errorf("接收失败：包裹 %q 当前归属 %q、状态 %q，不在运输单 %q 从源站 %q 在途，本次接收未执行",
2237						pid, p.Station, p.Status, shipment, sh.From)
2238				}
2239			}
2240			for _, mid := range sh.Parcels {
2241				if want[mid] {
2242					members = append(members, mid)
2243				}
2244			}
2245		} else {
2246			// 不选成员：本次集合为当时的全部尚未接收件，按发运保存顺序。
2247			for _, mid := range sh.Parcels {
2248				if !received[mid] {
2249					members = append(members, mid)
2250				}
2251			}
2252			if len(members) == 0 {
2253				return nil, false, fmt.Errorf("接收失败：运输单 %q 已全部接收（接收请求号 %q），没有尚未接收的成员，不能再次接收",
2254					shipment, sh.ReceivedBy)
2255			}
2256		}
2257	
2258		res = &ReceiveResult{
2259			Request:  request,
2260			Shipment: shipment,
2261			Station:  station,
2262			Parcels:  members,
2263			Time:     now,
2264			Explicit: explicit,
2265		}
2266		s.data.Receives[request] = res
2267		oldReceivedBy := sh.ReceivedBy
2268		if len(received)+len(members) == len(sh.Parcels) {
2269			sh.ReceivedBy = request // 全部成员到齐：运输单永久标记为已接收
2270		}
2271	
2272		// 记录旧值，落盘失败时整体回滚。
2273		prev := make(map[string]struct {
2274			station string
2275			status  string
2276			trail   []Event
2277		}, len(members))
2278		for _, pid := range members {
2279			p := s.data.Parcels[pid]
2280			prev[pid] = struct {
2281				station string
2282				status  string
2283				trail   []Event
2284			}{p.Station, p.Status, append([]Event(nil), p.Trail...)}
2285			p.Station = sh.To
2286			p.Status = statusInStation
2287			p.Trail = append(p.Trail, Event{
2288				Op:       "接收",
2289				Station:  sh.To,
2290				From:     sh.From,
2291				To:       sh.To,
2292				Shipment: shipment,
2293				Request:  request,
2294				Time:     now,
2295			})
2296		}
2297	
2298		if err := s.save(); err != nil {
2299			delete(s.data.Receives, request)
2300			sh.ReceivedBy = oldReceivedBy
2301			for pid, old := range prev {
2302				p := s.data.Parcels[pid]
2303				p.Station, p.Status = old.station, old.status
2304				p.Trail = old.trail
2305			}
2306			return nil, false, err
2307		}
2308		return res, false, nil
2309	}
