2427	// sameOrder 判断两个列表长度与逐元素顺序完全一致。
2428	func sameOrder(a, b []string) bool {
2429		if len(a) != len(b) {
2430			return false
2431		}
2432		for i := range a {
2433			if a[i] != b[i] {
2434				return false
2435			}
2436		}
2437		return true
2438	}
