189		}
190	
191		cleanReq, err := cleanID("请求号", *request)
192		if err != nil {
193			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
194			return exitBusiness
195		}
196		cleanFrom, err := cleanID("源站点", *from)
197		if err != nil {
