448				headline = "回执成功（请求号重复提交，返回首次保存的结果；该回执已撤销，未恢复回执或改变当前状态）"
449			}
450		}
451		fmt.Fprintf(stdout, "%s\n请求号: %s\n批次号: %s\n包裹编号: %s\n结果: %s\n",
452			headline, res.Request, res.Batch, res.Parcel, res.Result)
453		if res.Result == resultFailed {
