463	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
464	type receiptFileRecord struct {
465		Request string `json:"request"`
466		Batch   string `json:"batch"`
467		Parcel  string `json:"parcel"`
468		Result  string `json:"result"`
469		Reason  string `json:"reason"`
470	}
471	
472	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
473	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
474	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
475	// 都返回带记录位置的错误，整份不予导入。
476	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
477		raw, err := os.ReadFile(path)
478		if err != nil {
479			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
480		}
481		dec := json.NewDecoder(bytes.NewReader(raw))
482		dec.DisallowUnknownFields()
483		var records []receiptFileRecord
484		if err := dec.Decode(&records); err != nil {
485			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
486		}
487		var extra any
488		if err := dec.Decode(&extra); err != io.EOF {
489			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
490		}
491		if len(records) == 0 {
492			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
493		}
494	
495		clean := make([]ReceiptImportRecord, 0, len(records))
496		seen := make(map[string]bool, len(records))
497		for i, rawRec := range records {
498			rec, err := cleanReceiptImportRecord(rawRec)
499			if err != nil {
500				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
501			}
502			if seen[rec.Request] {
503				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
504			}
505			seen[rec.Request] = true
506			clean = append(clean, rec)
507		}
508		return clean, nil
509	}
510	
511	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
512	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
513	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
514		var rec ReceiptImportRecord
515		var err error
516		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
517			return rec, err
518		}
519		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
520			return rec, err
521		}
522		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
523			return rec, err
524		}
525		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
526			return rec, err
527		}
528		if rec.Result != resultSigned && rec.Result != resultFailed {
529			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
530		}
531		rec.Reason = strings.TrimSpace(raw.Reason)
532		if rec.Result == resultFailed && rec.Reason == "" {
533			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
534		}
535		if rec.Result == resultSigned && rec.Reason != "" {
536			return rec, fmt.Errorf("结果为签收时不可带原因")
537		}
538		return rec, nil
539	}
