    }
    res = &RerouteResult{Request: request, Shipment: shipment, From: cur, To: to, Reason: reason, Parcels: members, Time: now}
    s.data.Reroutes[request] = res
    sh.Reroutes = append(sh.Reroutes, request)
    // append trail events; station/status unchanged
    prev := ... trails
