func runParallel(t *testing.T, n int, mkArgs func(i int) []string) (outs, errs []string, codes []int) {
	t.Helper()
	outs, errs, codes = make([]string, n), make([]string, n), make([]int, n)
	start := make(chan struct{})
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
