			defer wg.Done()
			<-start
			var out, errb strings.Builder
			codes[i] = run(mkArgs(i), &out, &errb)
			outs[i], errs[i] = out.String(), errb.String()
		}(i)
	}
	close(start)
	wg.Wait()
	return outs, errs, codes
}

