			}
			if e.Shipment != open {
				return fmt.Errorf("%w: 包裹 %q 第 %d 条接收轨迹的运输单 %q 与当前在途运输单 %q 不匹配",
					ErrCorrupt, id, i+1, e.Shipment, open)
			}
