func TestCLIRerouteValidation(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "ledger.json")
	for _, args := range [][]string{
		{"register", "--id", "P001", "--station", "站点A"},
		{"ship", "--shipment", "S1", "--from", "站点A", "--to", "站点B", "--parcel", "P001"},
	} {
